begin;
do $test$
declare actor uuid:=gen_random_uuid();staff uuid:=gen_random_uuid();org uuid:=gen_random_uuid();s uuid:=gen_random_uuid();t uuid:=gen_random_uuid();batch uuid:=gen_random_uuid();run uuid:=gen_random_uuid();line uuid:=gen_random_uuid();req uuid:=gen_random_uuid();doc uuid:=gen_random_uuid();a jsonb;payload jsonb;result jsonb;before_doc jsonb;before_count integer;
begin
 select count(*) into before_count from public.receipt_upload_batches;
 insert into auth.users(id,email,email_confirmed_at,created_at,updated_at) select id,id||'@receipt-store.invalid',now(),now(),now() from unnest(array[actor,staff]) id;
 insert into public.profiles(id,display_name) select id,'門市更正回滾測試' from unnest(array[actor,staff]) id on conflict(id) do nothing;
 insert into public.organizations(id,name,business_type) values(org,'門市更正回滾測試','SINGLE_RESTAURANT');
 insert into public.stores(id,organization_id,name,store_code,created_by) values(s,org,'BeApe','MV'||substr(s::text,1,8),actor),(t,org,'Gras','MV'||substr(t::text,1,8),actor);
 insert into public.organization_members(organization_id,user_id,role,is_owner,can_manage_business) values(org,actor,'OWNER',true,true),(org,staff,'STAFF',false,false);
 insert into public.staff_identities(organization_id,user_id,display_name,created_by) select org,id,'門市更正測試',actor from unnest(array[actor,staff]) id;
 insert into public.store_memberships(store_id,organization_id,user_id,login_identifier,role,work_role,assigned_by,can_manage_business) values(s,org,actor,'mv-owner','OWNER','OWNER',actor,true),(t,org,actor,'mv-owner-target','OWNER','OWNER',actor,true),(s,org,staff,'mv-staff','STAFF','STAFF',actor,false);
 insert into public.receipt_upload_batches(id,organization_id,store_id,store_name,uploaded_by,status,work_date) values(batch,org,s,'BeApe',actor,'READY_FOR_REVIEW',current_date);
 insert into public.receipt_ocr_runs(id,organization_id,batch_id,version,provider,model,prompt_version,status,started_by) values(run,org,batch,1,'manual','test','test','SUCCEEDED',actor);
 insert into private.receipt_manual_rows(id,batch_id,run_id,supplier_name,product_name,unit,quantity,unit_price_ex_tax,line_subtotal_ex_tax,created_by) values(line,batch,run,'測試廠商','測試麵粉','包',2,100,200,actor);
 insert into public.receipt_documents(id,organization_id,batch_id,storage_path,original_filename,page_order,mime_type,uploaded_by) values(doc,org,batch,'test/'||doc::text,'原貨單.jpeg',1,'image/jpeg',actor);
 select to_jsonb(d) into before_doc from public.receipt_documents d where id=doc;
 perform set_config('request.jwt.claim.sub',actor::text,true);
 assert jsonb_array_length(public.get_receipt_store_choices(s))=2,'two permitted stores';
 a:=public.get_baihuayuan_receipt_accounts(s,null,null,null,batch)->0;
 payload:=jsonb_build_object('revision',a->'revision','source_fingerprint',a->>'source_fingerprint','header',jsonb_build_object('supplier_name','測試廠商','receipt_date',current_date,'document_number','MOVE-TEST'),'lines',a->'lines','adjustment',0,'tax',0,'total',200,'note','保留備註','checked',false,'entry_completed',true,'review_completed',true);
 -- stale revision must roll back without moving the batch
 begin perform public.correct_receipt_store(s,batch,t,payload||'{"revision":999999}',gen_random_uuid());raise exception 'stale accepted';exception when sqlstate 'PT409' or sqlstate '40001' then null;end;
 assert (select store_id=s from public.receipt_upload_batches where id=batch),'stale did not move';
 update public.store_memberships set access_mode='VIEW' where store_id=t and user_id=actor;
 begin perform public.correct_receipt_store(s,batch,t,payload,req);raise exception 'readonly accepted';exception when sqlstate '42501' then null;end;
 update public.store_memberships set access_mode='EDIT' where store_id=t and user_id=actor;
 perform set_config('request.jwt.claim.sub',staff::text,true);
 begin perform public.correct_receipt_store(s,batch,t,payload,req);raise exception 'staff accepted';exception when sqlstate '42501' then null;end;
 perform set_config('request.jwt.claim.sub','',true);
 begin perform public.correct_receipt_store(s,batch,t,payload,req);raise exception 'anonymous accepted';exception when sqlstate '42501' then null;end;
 perform set_config('request.jwt.claim.sub',actor::text,true);
 result:=public.correct_receipt_store(s,batch,t,payload,req);
 assert result=public.correct_receipt_store(s,batch,t,payload,req),'retry idempotent';
 assert result#>>'{account,moved_to_store_id}'=t::text,'target returned';
 assert jsonb_array_length(public.get_baihuayuan_receipt_accounts(s,null,null,null,batch))=0,'source list excludes';
 a:=public.get_baihuayuan_receipt_accounts(t,null,null,null,batch)->0;
 assert jsonb_array_length(a->'lines')=1,'detail preserved';
 assert (a->'lines'->0->>'quantity')::numeric=2,'quantity preserved';
 assert (a->'lines'->0->>'unit_price')::numeric=100,'price preserved';
 assert a->>'note'='保留備註','note preserved';
 assert (select to_jsonb(d)=before_doc from public.receipt_documents d where id=doc),'original file unchanged';
 assert (select store_id=t from private.receipt_account_edits where batch_id=batch),'edit owner moved';
 assert (select store_id=t from private.receipt_reconciliations where batch_id=batch),'account owner moved';
 assert (select count(*)=1 from public.audit_logs where entity_id=batch::text and action='receipt.store.correct'),'one audit';
 assert (select count(*)=before_count+1 from public.receipt_upload_batches),'no duplicate';
 perform set_config('request.jwt.claim.sub',staff::text,true);
 begin perform public.correct_receipt_store(s,batch,t,payload,req);raise exception 'unauthorized retry accepted';exception when sqlstate '42501' then null;end;
end $test$;
rollback;
